<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'; import { useI18n } from 'vue-i18n';
import { onAuthStateChanged, signInWithPopup, signOut as firebaseSignOut, type User } from 'firebase/auth';
import { collection, doc, getDoc, onSnapshot, setDoc, deleteDoc, query, orderBy, serverTimestamp } from 'firebase/firestore';
import { auth, db, googleProvider, firebaseConfigured } from './lib/firebase';
import type { Meal, MealType, DayPlan } from './types';
import { CalendarDays, ChefHat, Utensils, Plus, ChevronLeft, ChevronRight, Sun, Moon, Languages, Search, LogOut, X, Trash2, Pencil, Sparkles } from '@lucide/vue';
const {t,locale}=useI18n();
const user=ref<User|null>(null), access=ref(false), checking=ref(true), authError=ref('');
const meals=ref<Meal[]>([]), plans=ref<Record<string,DayPlan>>({}), activeTab=ref<'today'|'meals'|'plan'>('today');
const theme=ref<'dark'|'light'>(localStorage.getItem('diet-theme') as 'dark'|'light'||'dark');
const search=ref(''), modal=ref(false), editing=ref<Meal|null>(null), selectedDate=ref(new Date());
const form=ref({name:'',description:'',tags:[] as string[],rating:3});
const types:MealType[]=['breakfast','lunch','snack','dinner'];
const sortedMeals=computed(()=>meals.value.filter(m=>m.name.toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name)));
const dateKey=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const todayKey=dateKey(new Date()); const currentKey=computed(()=>dateKey(selectedDate.value));
const todayPlan=computed(()=>plans.value[todayKey]||{id:todayKey,date:todayKey,meals:{}});
const weekDays=computed(()=>{const d=new Date(selectedDate.value); const day=(d.getDay()+6)%7; d.setDate(d.getDate()-day); return Array.from({length:7},(_,i)=>{const x=new Date(d);x.setDate(d.getDate()+i);return x;});});
const dateLabel=(d:Date)=>new Intl.DateTimeFormat(locale.value==='it'?'it-IT':'en-US',{weekday:'short',day:'numeric',month:'short'}).format(d);
const fullDate=(d:Date)=>new Intl.DateTimeFormat(locale.value==='it'?'it-IT':'en-US',{weekday:'long',day:'numeric',month:'long'}).format(d);
let stopMeals:(()=>void)|undefined, stopPlans:(()=>void)|undefined;
async function checkAccess(u:User){if(!db)return; const snap=await getDoc(doc(db,'users',u.uid)); access.value=snap.exists()&&snap.data().enabled===true; checking.value=false; if(access.value)subscribe();}
function subscribe(){if(!db)return; stopMeals?.();stopPlans?.();stopMeals=onSnapshot(query(collection(db,'meals'),orderBy('name')),s=>meals.value=s.docs.map(d=>({id:d.id,...d.data()} as Meal)));stopPlans=onSnapshot(collection(db,'plan'),s=>{const next:Record<string,DayPlan>={};s.docs.forEach(d=>next[d.id]={id:d.id,...d.data()} as DayPlan);plans.value=next;});}
onMounted(()=>{if(!auth||!db){checking.value=false;return;}onAuthStateChanged(auth,async u=>{user.value=u;access.value=false;if(u)await checkAccess(u);else{checking.value=false;stopMeals?.();stopPlans?.();}})});
watch(theme,v=>{document.documentElement.dataset.theme=v;localStorage.setItem('diet-theme',v)},{immediate:true});
watch(locale,v=>localStorage.setItem('diet-language',v));
async function login(){if(!auth)return;authError.value='';try{await signInWithPopup(auth,googleProvider)}catch(e){authError.value=e instanceof Error?e.message:'Authentication failed'}}
async function logout(){if(auth)await firebaseSignOut(auth)}
function openMeal(meal?:Meal){editing.value=meal||null;form.value=meal?{name:meal.name,description:meal.description||'',tags:[...meal.tags],rating:meal.rating}:{name:'',description:'',tags:[],rating:3};modal.value=true;}
async function saveMeal(){if(!db||!form.value.name.trim())return;const payload={name:form.value.name.trim(),description:form.value.description.trim(),tags:form.value.tags,rating:form.value.rating,updatedAt:serverTimestamp()};if(editing.value)await setDoc(doc(db,'meals',editing.value.id),payload,{merge:true});else{const id=crypto.randomUUID();await setDoc(doc(db,'meals',id),{...payload,createdAt:serverTimestamp()});}modal.value=false;}
async function removeMeal(m:Meal){if(!db||!confirm(t('confirmDelete')))return;await deleteDoc(doc(db,'meals',m.id));}
async function setPlan(date:Date,type:MealType,mealId:string){if(!db)return;const key=dateKey(date),chosen=meals.value.find(m=>m.id===mealId);const day=plans.value[key]||{id:key,date:key,meals:{}};const next={...day.meals};if(chosen)next[type]={mealId:chosen.id,mealName:chosen.name};else delete next[type];await setDoc(doc(db,'plan',key),{date:key,meals:next},{merge:true});}
function shiftWeek(delta:number){const d=new Date(selectedDate.value);d.setDate(d.getDate()+delta*7);selectedDate.value=d;}
function tagLabel(tag:string){return t(tag)}
</script>
<template>
<div class="app-shell">
  <aside class="sidebar"><div class="brand"><div class="brand-mark"><Utensils :size="19"/></div><span>diet<span class="brand-dot">.</span></span></div>
    <nav><button v-for="tab in ['today','meals','plan'] as const" :key="tab" :class="['nav-item',{active:activeTab===tab}]" @click="activeTab=tab"><Sun v-if="tab==='today'"/><ChefHat v-else-if="tab==='meals'"/><CalendarDays v-else/><span>{{t(tab)}}</span><span v-if="tab==='today'" class="nav-today-dot"/></button></nav>
    <div class="sidebar-bottom"><div class="user-mini" v-if="user"><img v-if="user.photoURL" :src="user.photoURL"/><div v-else class="avatar">{{user.displayName?.[0]||'U'}}</div><div class="user-info"><b>{{user.displayName||'You'}}</b><small>{{user.email}}</small></div></div><div class="side-actions"><button class="icon-btn" @click="theme=theme==='dark'?'light':'dark'" :title="theme==='dark'?t('light'):t('dark')"><Sun v-if="theme==='dark'"/><Moon v-else/></button><button class="icon-btn" @click="locale=locale==='en'?'it':'en'" :title="t('language')"><Languages/></button><button v-if="user" class="icon-btn" @click="logout" :title="t('signOut')"><LogOut/></button></div></div>
  </aside>
  <main class="main-content">
    <header class="topbar"><div class="mobile-brand"><div class="brand-mark"><Utensils :size="17"/></div>diet<span class="brand-dot">.</span></div><div class="breadcrumb">PERSONAL SPACE <span>/</span> {{t(activeTab).toUpperCase()}}</div><div class="top-actions"><span class="today-pill"><span></span>{{dateLabel(new Date())}}</span><button class="icon-btn mobile-theme" @click="theme=theme==='dark'?'light':'dark'"><Sun v-if="theme==='dark'"/><Moon v-else/></button></div></header>
    <div v-if="!firebaseConfigured" class="center-state"><div class="state-icon"><Sparkles/></div><h1>{{t('welcome')}}</h1><p>{{t('setup')}}</p><code>cp .env.example .env.local</code></div>
    <div v-else-if="checking" class="center-state"><div class="loader"/><p>Loading your space…</p></div>
    <div v-else-if="!user" class="center-state login-state"><div class="hero-orbit"><div class="hero-plate"><Utensils :size="34"/></div></div><p class="eyebrow">A MORE MINDFUL ROUTINE</p><h1>{{t('welcome')}}</h1><p class="muted">Plan ahead. Eat well. Find your rhythm.</p><button class="primary-btn google-btn" @click="login"><span class="google-g">G</span>{{t('signIn')}}</button><p v-if="authError" class="error-text">{{authError}}</p></div>
    <div v-else-if="!access" class="center-state"><div class="state-icon"><X/></div><h2>{{t('accessDenied')}}</h2><p class="muted">Ask the administrator to enable your UID in Firestore.</p><code>{{user.uid}}</code><button class="text-btn" @click="logout">{{t('signOut')}}</button></div>
    <template v-else>
      <section v-if="activeTab==='today'" class="page"><div class="page-heading"><div><p class="eyebrow">{{fullDate(new Date()).toUpperCase()}}</p><h1>{{t('todayTitle')}}<span class="heading-period">.</span></h1><p class="muted">{{t('todaySub')}}</p></div><div class="heading-decoration"><span>01</span><div/></div></div><div class="meal-grid"><article v-for="(type,i) in types" :key="type" class="meal-card" :style="{'--delay':`${i*65}ms`}"><div class="meal-card-top"><span class="meal-index">0{{i+1}}</span><span class="meal-type">{{t(type)}}</span><span class="meal-symbol">{{['☀','◒','◉','☾'][i]}}</span></div><div class="meal-card-body"><template v-if="todayPlan.meals[type]"><h3>{{todayPlan.meals[type]?.mealName}}</h3><p class="meal-description">{{meals.find(m=>m.id===todayPlan.meals[type]?.mealId)?.description||'—'}}</p></template><p v-else class="empty-hint">{{t('noMeal')}}</p></div><div class="meal-card-foot"><select :value="todayPlan.meals[type]?.mealId||''" @change="setPlan(new Date(),type,($event.target as HTMLSelectElement).value)"><option value="">{{t('chooseMeal')}}</option><option v-for="m in meals" :key="m.id" :value="m.id">{{m.name}}</option></select></div></article></div><div class="bottom-note"><Sparkles :size="15"/><span>A good day starts with a little planning.</span></div></section>
      <section v-else-if="activeTab==='meals'" class="page"><div class="page-heading compact"><div><p class="eyebrow">YOUR PERSONAL COLLECTION</p><h1>{{t('allMeals')}}<span class="heading-period">.</span></h1><p class="muted">{{t('mealCount',{count:meals.length})}}</p></div><button class="primary-btn" @click="openMeal()"><Plus :size="17"/>{{t('addMeal')}}</button></div><div class="list-toolbar"><div class="search-box"><Search :size="17"/><input v-model="search" :placeholder="t('search')"/></div><span class="sort-label">{{t('alphabetical')}} <span>↕</span></span></div><div v-if="sortedMeals.length" class="meals-list"><article v-for="(m,i) in sortedMeals" :key="m.id" class="meal-row"><div class="meal-row-number">{{String(i+1).padStart(2,'0')}}</div><div class="meal-row-main"><h3>{{m.name}}</h3><p v-if="m.description">{{m.description}}</p><div class="tag-list"><span v-for="tag in m.tags" :key="tag" class="nutrition-tag" :class="tag">{{tagLabel(tag)}}</span></div></div><div class="frequency"><div class="frequency-label">{{t('rating')}}</div><div class="frequency-dots"><i v-for="n in 5" :key="n" :class="{filled:n<=m.rating,often:m.rating>=4,rare:m.rating<=2}"/></div><small :class="m.rating>=4?'often':m.rating<=2?'rare':''">{{m.rating}} / 5</small></div><div class="row-actions"><button class="icon-btn" @click="openMeal(m)"><Pencil/></button><button class="icon-btn danger" @click="removeMeal(m)"><Trash2/></button></div></article></div><div v-else class="empty-collection"><div class="state-icon"><ChefHat/></div><h3>{{t('noMeals')}}</h3><button class="text-btn" @click="openMeal()">{{t('addMeal')}} +</button></div></section>
      <section v-else class="page"><div class="page-heading compact"><div><p class="eyebrow">MAKE ROOM FOR VARIETY</p><h1>{{t('plan')}}<span class="heading-period">.</span></h1><p class="muted">{{t('weekOf')}} {{dateLabel(weekDays[0])}}</p></div><div class="week-controls"><button class="icon-btn" @click="shiftWeek(-1)"><ChevronLeft/></button><button class="icon-btn" @click="selectedDate=new Date()">{{t('todayFocus')}}</button><button class="icon-btn" @click="shiftWeek(1)"><ChevronRight/></button></div></div><div class="week-strip"><button v-for="d in weekDays" :key="dateKey(d)" :class="['day-tab',{selected:dateKey(d)===currentKey,istoday:dateKey(d)===todayKey}]" @click="selectedDate=d"><small>{{new Intl.DateTimeFormat(locale==='it'?'it-IT':'en-US',{weekday:'short'}).format(d)}}</small><b>{{d.getDate()}}</b><i/></button></div><div class="selected-day-heading"><div><p class="eyebrow">{{dateKey(selectedDate)===todayKey?t('todayFocus').toUpperCase():'DAILY OVERVIEW'}}</p><h2>{{fullDate(selectedDate)}}</h2></div><span class="day-count">{{Object.keys((plans[currentKey]?.meals)||{}).length}} / 4</span></div><div class="plan-list"><article v-for="(type,i) in types" :key="type" class="plan-row"><div class="plan-time"><span>{{['08:00','13:00','16:00','20:00'][i]}}</span><div class="timeline-dot"/></div><div class="plan-card"><div><small>{{t(type)}}</small><h3>{{plans[currentKey]?.meals[type]?.mealName||t('emptyDay')}}</h3></div><select :value="plans[currentKey]?.meals[type]?.mealId||''" @change="setPlan(selectedDate,type,($event.target as HTMLSelectElement).value)"><option value="">{{t('selectDish')}}</option><option v-for="m in meals" :key="m.id" :value="m.id">{{m.name}}</option></select></div></article></div></section>
    </template>
  </main>
  <div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="meal-modal"><div class="modal-header"><div><p class="eyebrow">MEAL LIBRARY</p><h2>{{editing?t('editMeal'):t('addMeal')}}</h2></div><button class="icon-btn" @click="modal=false"><X/></button></div><form @submit.prevent="saveMeal"><label>{{t('mealName')}}<input v-model="form.name" required maxlength="90" autofocus/></label><label>{{t('description')}}<textarea v-model="form.description" rows="3" maxlength="300"/></label><fieldset><legend>{{t('tags')}}</legend><label v-for="tag in ['carbs','protein','fat']" :key="tag" class="check-label"><input v-model="form.tags" type="checkbox" :value="tag"/><span>{{t(tag)}}</span></label></fieldset><div class="rating-editor"><div><label>{{t('rating')}}</label><small>{{t('ratingHelp')}}</small></div><div class="rating-stepper"><button type="button" @click="form.rating=Math.max(1,form.rating-1)">−</button><b>{{form.rating}}</b><button type="button" @click="form.rating=Math.min(5,form.rating+1)">+</button></div></div><div class="modal-actions"><button type="button" class="secondary-btn" @click="modal=false">{{t('cancel')}}</button><button class="primary-btn" type="submit">{{t('save')}}</button></div></form></section></div>
</div>
</template>
